"""Auto-generated TouchDesigner Network Builder: Course 01: Market Hall Dome 180-deg Equidistant Domemaster Rig

4096x4096 CubeMap to 180-deg Equidistant Fisheye pipeline + Spout2/NDI & OSC bridge.
Generated by Mo360 Antigravity <-> TouchDesigner Bridge (Mode B).
Run inside TouchDesigner Textport or pass via startup script.
"""

import json

PROJECT_NAME = 'course01_fulldome_180_rig'
PARENT_PATH = '/project1'
TARGET_FPS = 60


def _resolve_op(op_type_name):
    import td
    if hasattr(td, op_type_name):
        return getattr(td, op_type_name)
    low = op_type_name.lower()
    for attr in dir(td):
        if attr.lower() == low:
            return getattr(td, attr)
    raise ValueError(f"Unknown TouchDesigner operator type: {op_type_name}")


def _set_params(node, params):
    for key, val in params.items():
        if hasattr(node.par, key):
            setattr(node.par, key, val)


def build_network(parent_path=PARENT_PATH):
    import td
    td.project.cookRate = TARGET_FPS
    root = op(parent_path)
    if root is None:
        root = op('/').create(td.baseCOMP, parent_path.strip('/'))

    comp = root.op('course01_fulldome_180_rig')
    if comp is not None:
        comp.destroy()
    comp = root.create(td.baseCOMP, 'course01_fulldome_180_rig')
    comp.nodeX = 0
    comp.nodeY = 0

    created = {}
    # 3D Scene Geometry
    _node = comp.create(_resolve_op('geometryCOMP'), 'geo_dome_world')
    _node.nodeX = 0
    _node.nodeY = 220
    _set_params(_node, {'tx': 0, 'ty': 0, 'tz': 0})
    created['geo_dome_world'] = _node
    # Zenith Rig Camera
    _node = comp.create(_resolve_op('cameraCOMP'), 'cam_zenith')
    _node.nodeX = 0
    _node.nodeY = 60
    _set_params(_node, {'rx': 90, 'fov': 90})
    created['cam_zenith'] = _node
    # Warm Sanctuary Key Light
    _node = comp.create(_resolve_op('lightCOMP'), 'light_key')
    _node.nodeX = 0
    _node.nodeY = -90
    _set_params(_node, {'dimmer': 1.4})
    created['light_key'] = _node
    # CubeMap 6-Face Render
    _node = comp.create(_resolve_op('renderTOP'), 'render_cubemap')
    _node.nodeX = 260
    _node.nodeY = 220
    _set_params(_node, {'resolutionw': 2048, 'resolutionh': 2048, 'rendermode': 'cubemap'})
    created['render_cubemap'] = _node
    # 180-deg Equidistant Fisheye
    _node = comp.create(_resolve_op('projectionTOP'), 'proj_equidistant')
    _node.nodeX = 520
    _node.nodeY = 220
    _set_params(_node, {'input': 'cubemap', 'output': 'fisheye', 'fisheyefov': 180, 'resolutionw': 4096, 'resolutionh': 4096})
    created['proj_equidistant'] = _node
    # Springline Mask
    _node = comp.create(_resolve_op('circleTOP'), 'dome_circle_mask')
    _node.nodeX = 520
    _node.nodeY = 40
    _set_params(_node, {'radiusx': 0.5, 'radiusy': 0.5, 'resolutionw': 4096, 'resolutionh': 4096})
    created['dome_circle_mask'] = _node
    # Clean Circular Domemaster
    _node = comp.create(_resolve_op('compositeTOP'), 'comp_domemaster')
    _node.nodeX = 780
    _node.nodeY = 220
    _set_params(_node, {'operand': 'multiply'})
    created['comp_domemaster'] = _node
    # Spout2 4K Dome Output
    _node = comp.create(_resolve_op('spoutOutTOP'), 'spout_domemaster')
    _node.nodeX = 1040
    _node.nodeY = 280
    _set_params(_node, {'sendername': 'MO360_DOMEMASTER_4K'})
    created['spout_domemaster'] = _node
    # NDI 4K Dome Output
    _node = comp.create(_resolve_op('ndiOutTOP'), 'ndi_domemaster')
    _node.nodeX = 1040
    _node.nodeY = 120
    _set_params(_node, {'name': 'MO360_DOMEMASTER_NDI'})
    created['ndi_domemaster'] = _node
    # OSC Telemetry from UE 5.8
    _node = comp.create(_resolve_op('oscinCHOP'), 'osc_in_ue')
    _node.nodeX = 260
    _node.nodeY = -140
    _set_params(_node, {'port': 9000})
    created['osc_in_ue'] = _node

    # Wire signal flow
    created['proj_equidistant'].inputConnectors[0].connect(created['render_cubemap'].outputConnectors[0])
    created['comp_domemaster'].inputConnectors[0].connect(created['proj_equidistant'].outputConnectors[0])
    created['comp_domemaster'].inputConnectors[1].connect(created['dome_circle_mask'].outputConnectors[0])
    created['spout_domemaster'].inputConnectors[0].connect(created['comp_domemaster'].outputConnectors[0])
    created['ndi_domemaster'].inputConnectors[0].connect(created['comp_domemaster'].outputConnectors[0])

    print(f"[Mo360-TD] Built {len(created)} operators inside {comp.path}")
    return comp


if __name__ == "__main__":
    build_network()
